mapper.select:
SELECT d.patient_id AS patientId, d.encounter_id AS encounterId, p.name AS name, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) AS age, p.gender_enum AS genderEnum, p.phone AS phone, MAX(d.status_enum) AS statusEnum, d.dispense_enum AS dispenseEnum, COUNT(d.id) AS drugCount, MAX(d.created_at) AS createdAt FROM med_medication_dispense d JOIN adm_patient p ON p.id = d.patient_id WHERE d.is_deleted = 0
AND d.dispense_enum = #{query.dispenseEnum}
AND d.patient_id = #{query.patientId}
AND d.encounter_id = #{query.encounterId}
AND d.status_enum = #{query.statusEnum}
AND p.name LIKE CONCAT('%', #{query.name}, '%')
AND d.created_at >= #{query.startTime}
AND d.created_at <= #{query.endTime}
GROUP BY d.encounter_id, d.patient_id, p.name, p.birth_date, p.gender_enum, p.phone, d.dispense_enum ORDER BY MAX(d.created_at) DESC
